local LuaTypeProviderFactory = require(script.Parent)

local source = game.ReplicatedStorage._robloxManifest.LuaTypes
return function()
	describe("LuaTypeProviderFactory", function()
		it("应该返回一个有效的LuaTypeProvider", function()
			local mockSource = source

			local provider = LuaTypeProviderFactory(mockSource)

			expect(provider.IsLuaTypeProvider).to.equal(true)
			expect(typeof(provider.GetType)).to.equal("function")
			expect(typeof(provider.GetTypeByName)).to.equal("function")
		end)

		it("应该能够通过名称获取类型", function()
			local mockSource = source

			local provider = LuaTypeProviderFactory(mockSource)
			local testType = provider.GetType("game.ReplicatedStorage.Systems.UnitTests.SystemA.ComponentA")

			expect(testType).to.be.ok()
			expect(testType.FullName).to.equal("game.ReplicatedStorage.Systems.UnitTests.SystemA.ComponentA")
		end)

		it("应该能够通过键获取类型", function() end)
	end)
end
